//! Path include/exclude filtering for analysis runs.
//!
//! Excludes vendor, third-party, and generated files from analysis. It uses
//! [`is_vendor`] (a faithful reproduction of `src-d/enry`'s `IsVendor`) as the
//! foundation for vendor detection and adds supplementary generated-file name
//! patterns that enry does not cover.
//!
//! A [`Filter`] is immutable after construction and safe for concurrent use
//! (it is [`Send`] + [`Sync`]).
//!
//! # Examples
//!
//! ```
//! use cf_pathfilter::Filter;
//!
//! let f = Filter::new();
//! assert!(f.is_excluded("vendor/github.com/foo/bar.go")); // vendored
//! assert!(f.is_excluded("api/types.pb.go"));              // generated suffix
//! assert!(f.is_excluded("pkg/mock_service.go"));          // generated prefix
//! assert!(!f.is_excluded("internal/server/handler.go"));  // normal source
//! ```
//!
//! ## Compatibility note (DESIGN §2.6)
//!
//! This crate is decision-parity-critical: its boolean include/exclude result
//! selects which files flow into machine reports, whose bytes are pinned
//! against the reference binary by `rust/tests/compat`. Vendor detection
//! therefore vendors the same enry `data/vendor.go` regex tables (generated by
//! `build.rs` from the pinned enry source, with [`vendor_data`] as the
//! checked-in fallback), and the generated-file rule tables below are part of
//! that frozen contract.

#![forbid(unsafe_code)]

pub mod enry_vendor;
mod vendor_data;

pub use enry_vendor::is_vendor;

/// How many bytes of the file header to scan for generated markers. Keeps the
/// check fast even for large files.
const GENERATED_MARKER_SCAN_LIMIT: usize = 512;

/// Byte patterns found in the first line or header comment of generated files.
/// Checking a small prefix is cheap and avoids parsing. Pattern set and order
/// are part of the compatibility contract.
const GENERATED_MARKERS: &[&[u8]] = &[
    b"DO NOT EDIT",
    b"Code generated",
    b"AUTO-GENERATED",
    b"auto-generated",
    b"Autogenerated",
    b"@generated",
];

/// File suffixes indicating generated code that should not be structurally
/// analyzed. These produce noise in UAST-based metrics and their parse trees
/// consume excessive tree-sitter memory.
const DEFAULT_SUFFIXES: &[&str] = &[
    // Go generated files.
    ".pb.go",
    ".pb.gw.go",
    ".generated.go",
    ".deepcopy.go",
    "_string.go",   // stringer output.
    "_enumer.go",   // enumer output.
    "_easyjson.go", // easyjson output.
    // Protocol buffer outputs for other languages.
    "_pb2.py",
    "_pb2_grpc.py",
    ".pb.cc",
    ".pb.h",
    ".grpc.pb.cc",
    ".grpc.pb.h",
    // Minified / bundled assets.
    ".min.js",
    ".min.css",
    ".bundle.js",
];

/// Filename prefixes (matched against the path's base name) indicating
/// generated code.
const DEFAULT_FILENAME_PREFIXES: &[&str] = &[
    "zz_generated", // Kubernetes code-generator output.
    "mock_",        // mockgen output.
    "fake_",        // counterfeiter output.
    "wire_gen",     // Google Wire.
];

/// Returns the final path element of a slash-separated repository path.
///
/// Semantics (reference-implementation behavior, pinned by tests):
/// - empty input returns `"."`;
/// - trailing slashes are stripped;
/// - if nothing remains after stripping, returns `"/"`;
/// - otherwise returns the substring after the final remaining slash.
///
/// Inputs are always forward-slash repository paths, so only `/` is treated
/// as a separator.
fn path_base(path: &str) -> &str {
    if path.is_empty() {
        return ".";
    }

    // Strip trailing slashes.
    let mut end = path.len();
    while end > 0 && path.as_bytes()[end - 1] == b'/' {
        end -= 1;
    }
    let trimmed = &path[..end];
    if trimmed.is_empty() {
        // Path was all slashes.
        return "/";
    }

    trimmed.rfind('/').map_or(trimmed, |idx| &trimmed[idx + 1..])
}

/// Checks the file header for common generated-file markers: scans at most
/// [`GENERATED_MARKER_SCAN_LIMIT`] bytes and returns `true` if any marker
/// appears as a substring.
fn has_generated_marker(content: &[u8]) -> bool {
    let header = if content.len() > GENERATED_MARKER_SCAN_LIMIT {
        &content[..GENERATED_MARKER_SCAN_LIMIT]
    } else {
        content
    };

    GENERATED_MARKERS
        .iter()
        .any(|marker| contains_subslice(header, marker))
}

/// Reports whether `haystack` contains `needle` as a contiguous subslice
/// (an empty needle always matches).
fn contains_subslice(haystack: &[u8], needle: &[u8]) -> bool {
    if needle.is_empty() {
        return true;
    }
    if needle.len() > haystack.len() {
        return false;
    }
    haystack
        .windows(needle.len())
        .any(|window| window == needle)
}

/// Determines whether a file should be excluded from analysis. Combines enry
/// vendor detection with generated-file name patterns.
///
/// Construct with [`Filter::new`] (built-in rules) or
/// [`Filter::with_rules`] / the [`builder`](Filter::builder) for custom rule
/// sets. The struct is immutable after construction.
#[derive(Debug, Clone)]
pub struct Filter {
    /// File suffix matches (e.g., `.pb.go`).
    suffixes: Vec<String>,
    /// Filename prefix matches (e.g., `zz_generated`).
    filename_pfx: Vec<String>,
}

impl Filter {
    /// Creates a `Filter` with the built-in [`DEFAULT_SUFFIXES`] /
    /// [`DEFAULT_FILENAME_PREFIXES`] rules.
    ///
    /// Vendor detection is always handled by the enry tables, regardless of
    /// these rules.
    #[must_use]
    pub fn new() -> Self {
        Self::builder().build()
    }

    /// Creates a `Filter` with explicit suffix and filename-prefix rules.
    ///
    /// If **both** rule sets are empty the built-in default rules are applied
    /// instead (the "no rules configured → defaults" fallback).
    #[must_use]
    pub fn with_rules<S, P>(suffixes: S, filename_prefixes: P) -> Self
    where
        S: IntoIterator,
        S::Item: Into<String>,
        P: IntoIterator,
        P::Item: Into<String>,
    {
        Self::builder()
            .suffixes(suffixes)
            .filename_prefixes(filename_prefixes)
            .build()
    }

    /// Returns a [`FilterBuilder`] for configuring custom rules.
    #[must_use]
    pub fn builder() -> FilterBuilder {
        FilterBuilder::default()
    }

    /// Reports whether the given path should be excluded from analysis.
    ///
    /// Path-only check (no file content needed), in fixed precedence order:
    /// 1. [`is_vendor`] → excluded;
    /// 2. any configured suffix matches the full path → excluded;
    /// 3. any configured filename prefix matches the path's base name → excluded;
    /// 4. otherwise not excluded.
    #[must_use]
    pub fn is_excluded(&self, file_path: &str) -> bool {
        if is_vendor(file_path) {
            return true;
        }

        if self.suffixes.iter().any(|s| file_path.ends_with(s)) {
            return true;
        }

        if !self.filename_pfx.is_empty() {
            let base = path_base(file_path);
            if self.filename_pfx.iter().any(|p| base.starts_with(p)) {
                return true;
            }
        }

        false
    }

    /// Performs path-only checks first, then inspects the file header for
    /// generated-file markers (e.g., `DO NOT EDIT`).
    #[must_use]
    pub fn is_excluded_with_content(&self, file_path: &str, content: &[u8]) -> bool {
        if self.is_excluded(file_path) {
            return true;
        }

        !content.is_empty() && has_generated_marker(content)
    }

    /// Checks suffix and filename-prefix rules only (no vendor check). Allows
    /// callers to distinguish vendor files from generated files.
    #[must_use]
    pub fn is_generated_path(&self, file_path: &str) -> bool {
        if self.suffixes.iter().any(|s| file_path.ends_with(s)) {
            return true;
        }

        if !self.filename_pfx.is_empty() {
            let base = path_base(file_path);
            if self.filename_pfx.iter().any(|p| base.starts_with(p)) {
                return true;
            }
        }

        false
    }

    /// Checks file content for generated-file header markers.
    #[must_use]
    pub fn is_generated_content(&self, content: &[u8]) -> bool {
        !content.is_empty() && has_generated_marker(content)
    }

    /// Returns the configured suffix rules (test/inspection helper).
    #[must_use]
    pub fn suffixes(&self) -> &[String] {
        &self.suffixes
    }

    /// Returns the configured filename-prefix rules (test/inspection helper).
    #[must_use]
    pub fn filename_prefixes(&self) -> &[String] {
        &self.filename_pfx
    }
}

impl Default for Filter {
    fn default() -> Self {
        Self::new()
    }
}

/// Builder for [`Filter`].
///
/// Calling [`build`](FilterBuilder::build) with no rules set applies the
/// built-in defaults.
#[derive(Debug, Default, Clone)]
pub struct FilterBuilder {
    suffixes: Vec<String>,
    filename_pfx: Vec<String>,
}

impl FilterBuilder {
    /// Sets the suffix rules, replacing any previously set.
    #[must_use]
    pub fn suffixes<S>(mut self, suffixes: S) -> Self
    where
        S: IntoIterator,
        S::Item: Into<String>,
    {
        self.suffixes = suffixes.into_iter().map(Into::into).collect();
        self
    }

    /// Sets the filename-prefix rules, replacing any previously set.
    #[must_use]
    pub fn filename_prefixes<P>(mut self, prefixes: P) -> Self
    where
        P: IntoIterator,
        P::Item: Into<String>,
    {
        self.filename_pfx = prefixes.into_iter().map(Into::into).collect();
        self
    }

    /// Builds the [`Filter`].
    ///
    /// If both rule lists are empty, the built-in [`DEFAULT_SUFFIXES`] /
    /// [`DEFAULT_FILENAME_PREFIXES`] are applied.
    #[must_use]
    pub fn build(self) -> Filter {
        if self.suffixes.is_empty() && self.filename_pfx.is_empty() {
            return Filter {
                suffixes: DEFAULT_SUFFIXES.iter().map(|s| (*s).to_string()).collect(),
                filename_pfx: DEFAULT_FILENAME_PREFIXES
                    .iter()
                    .map(|s| (*s).to_string())
                    .collect(),
            };
        }

        Filter {
            suffixes: self.suffixes,
            filename_pfx: self.filename_pfx,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // --- Ported from the reference suite (pathfilter_test.go) ---

    #[test]
    fn is_excluded_vendor_paths() {
        let f = Filter::new();

        // The enry vendor table covers these patterns.
        assert!(f.is_excluded("vendor/github.com/foo/bar.go"));
        assert!(f.is_excluded("node_modules/lodash/index.js"));
        assert!(f.is_excluded("bower_components/jquery/jquery.js"));
        assert!(f.is_excluded("Godeps/_workspace/src/foo/bar.go"));
    }

    #[test]
    fn is_excluded_nested_vendor_paths() {
        let f = Filter::new();

        assert!(f.is_excluded("pkg/internal/vendor/foo/bar.go"));
        assert!(f.is_excluded("packages/app/node_modules/react/index.js"));
    }

    #[test]
    fn is_excluded_generated_suffixes() {
        let f = Filter::new();

        assert!(f.is_excluded("api/types.pb.go"));
        assert!(f.is_excluded("api/types.pb.gw.go"));
        assert!(f.is_excluded("pkg/foo.generated.go"));
        assert!(f.is_excluded("pkg/types.deepcopy.go"));
        assert!(f.is_excluded("pkg/status_string.go"));
        assert!(f.is_excluded("pkg/color_enumer.go"));
        assert!(f.is_excluded("pkg/model_easyjson.go"));
        assert!(f.is_excluded("proto/service_pb2.py"));
        assert!(f.is_excluded("proto/service_pb2_grpc.py"));
        assert!(f.is_excluded("proto/service.pb.cc"));
        assert!(f.is_excluded("proto/service.pb.h"));
        assert!(f.is_excluded("proto/service.grpc.pb.cc"));
        assert!(f.is_excluded("proto/service.grpc.pb.h"));
        assert!(f.is_excluded("static/app.min.js"));
        assert!(f.is_excluded("static/style.min.css"));
        assert!(f.is_excluded("dist/app.bundle.js"));
    }

    #[test]
    fn is_excluded_generated_filename_prefixes() {
        let f = Filter::new();

        assert!(f.is_excluded("pkg/api/zz_generated_deepcopy.go"));
        assert!(f.is_excluded("pkg/api/zz_generated.defaults.go"));
        assert!(f.is_excluded("pkg/mock_service.go"));
        assert!(f.is_excluded("pkg/fake_client.go"));
        assert!(f.is_excluded("internal/wire_gen.go"));
    }

    #[test]
    fn is_excluded_non_excluded_paths() {
        let f = Filter::new();

        assert!(!f.is_excluded("main.go"));
        assert!(!f.is_excluded("internal/server/handler.go"));
        assert!(!f.is_excluded("pkg/api/types.go"));
        assert!(!f.is_excluded("cmd/app/main.go"));
        assert!(!f.is_excluded("src/index.ts"));
        assert!(!f.is_excluded("lib/utils.py"));
        assert!(!f.is_excluded("test/integration_test.go"));
    }

    #[test]
    fn is_excluded_empty_path() {
        let f = Filter::new();
        assert!(!f.is_excluded(""));
    }

    #[test]
    fn is_excluded_with_content_generated_file() {
        let f = Filter::new();

        let cases: &[(&str, &str, bool)] = &[
            (
                "Code generated header",
                "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\n",
                true,
            ),
            (
                "DO NOT EDIT header",
                "// DO NOT EDIT. Auto-generated.\npackage api\n",
                true,
            ),
            (
                "AUTO-GENERATED header",
                "// AUTO-GENERATED FILE\npackage api\n",
                true,
            ),
            (
                "auto-generated header",
                "// auto-generated by tool\npackage api\n",
                true,
            ),
            (
                "Autogenerated header",
                "/* Autogenerated */\npackage api\n",
                true,
            ),
            ("@generated annotation", "// @generated\npackage api\n", true),
            ("Normal code", "package api\n\ntype Foo struct{}\n", false),
        ];

        for (name, content, excluded) in cases {
            assert_eq!(
                *excluded,
                f.is_excluded_with_content("pkg/api/types.go", content.as_bytes()),
                "{name}"
            );
        }
    }

    #[test]
    fn is_excluded_with_content_nil_content() {
        let f = Filter::new();

        // With empty content, falls back to path-only check.
        assert!(f.is_excluded_with_content("vendor/foo/bar.go", b""));
        assert!(!f.is_excluded_with_content("main.go", b""));
    }

    #[test]
    fn is_generated_path() {
        let f = Filter::new();

        // Generated suffixes should match.
        assert!(f.is_generated_path("api/types.pb.go"));
        assert!(f.is_generated_path("static/app.min.js"));

        // Generated filename prefixes should match.
        assert!(f.is_generated_path("pkg/zz_generated_deepcopy.go"));
        assert!(f.is_generated_path("pkg/mock_service.go"));

        // Vendor paths should NOT match (is_generated_path skips the vendor check).
        assert!(!f.is_generated_path("vendor/github.com/foo/bar.go"));
        assert!(!f.is_generated_path("node_modules/lodash/index.js"));

        // Normal source files should NOT match.
        assert!(!f.is_generated_path("main.go"));
        assert!(!f.is_generated_path("internal/server/handler.go"));
    }

    #[test]
    fn is_generated_content() {
        let f = Filter::new();

        assert!(f.is_generated_content(
            b"// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\n"
        ));
        assert!(f.is_generated_content(b"// @generated\npackage api\n"));
        assert!(f.is_generated_content(b"// AUTO-GENERATED FILE\npackage api\n"));

        // Normal code should NOT match.
        assert!(!f.is_generated_content(b"package api\n\ntype Foo struct{}\n"));

        // Empty content should NOT match.
        assert!(!f.is_generated_content(b""));
    }

    #[test]
    fn new_default_rules_applied() {
        let f = Filter::new();

        // Verify default suffixes and filename prefixes are populated.
        assert!(!f.suffixes().is_empty());
        assert!(!f.filename_prefixes().is_empty());
    }

    // --- Additional coverage for ported helpers ---

    #[test]
    fn path_base_semantics() {
        assert_eq!(path_base(""), ".");
        assert_eq!(path_base("/"), "/");
        assert_eq!(path_base("///"), "/");
        assert_eq!(path_base("a/b/c.go"), "c.go");
        assert_eq!(path_base("c.go"), "c.go");
        assert_eq!(path_base("a/b/"), "b");
        assert_eq!(path_base("zz_generated.go"), "zz_generated.go");
    }

    #[test]
    fn scan_limit_truncates_header() {
        // A marker placed beyond the 512-byte scan limit must NOT be found.
        let mut content = vec![b' '; GENERATED_MARKER_SCAN_LIMIT];
        content.extend_from_slice(b"DO NOT EDIT");
        assert!(!has_generated_marker(&content));

        // A marker ending exactly at the limit IS found.
        let mut content2 = vec![b' '; GENERATED_MARKER_SCAN_LIMIT - b"DO NOT EDIT".len()];
        content2.extend_from_slice(b"DO NOT EDIT");
        assert_eq!(content2.len(), GENERATED_MARKER_SCAN_LIMIT);
        assert!(has_generated_marker(&content2));
    }

    #[test]
    fn custom_rules_override_defaults() {
        let f = Filter::with_rules([".xyz"], ["gen_"]);
        assert!(f.is_generated_path("foo.xyz"));
        assert!(f.is_generated_path("dir/gen_thing.rs"));
        // Default suffix no longer applies.
        assert!(!f.is_generated_path("foo.pb.go"));
    }
}
